import { CommonModule } from '@angular/common';
import { Component, computed, effect, ElementRef, HostListener, inject, input, output, signal, viewChild, viewChildren } from '@angular/core';
import { ApIconComponent } from "../ap-icon/ap-icon.component";
import { ApSelectOption } from './ap-select.interface';

@Component({
  selector: 'ap-select',
  imports: [CommonModule, ApIconComponent],
  templateUrl: './ap-select.component.html',
  styleUrl: './ap-select.component.css'
})
export class ApSelectComponent {
  /** 標籤文字 */
  label = input<string | null>(null);
  /** 元件樣式變化 */
  readonly variant = input<'default' | 'game-ui'>('default');
  /** 預設選中的值 */
  readonly selected = input<string | null>(null);
  /** 下拉選單是否開啟 */
  readonly isOpen = signal(false);
  /** 選中的選項 */
  readonly currentOption = signal<ApSelectOption | null>(null);
  /** 元件大小 */
  readonly size = input<'small' | 'medium' | 'large'>('medium');
  /** 主色調 */
  readonly accentColor = input<'orange' | 'yellow' | 'slate'>('orange');
  /** 是否禁用元件 */
  readonly disabled = input<boolean>(false);
  /** 預設提示文字 */
  readonly placeholder = input('Select an option');
  /** 是否在選項最前面加入「全部」選項 */
  readonly showAllOption = input<boolean>(false);
  /** 轉換後的選項陣列 */
  readonly options = input<ApSelectOption[]>([
    { value: 'option1', label: 'Option 1',},
    { value: 'option2', label: 'Option 2' },
    { value: 'option3', label: 'Option 3' }
  ]);
  /** 加上「全部」選項後，實際顯示在下拉選單的選項陣列 */
  readonly displayOptions = computed<ApSelectOption[]>(() =>
    this.showAllOption()
      ? [{ value: 'all', label: this.placeholder() }, ...this.options()]
      : this.options(),
  );
  /** 選項改變事件 */
  readonly onSelect = output<any>();
  /** 下拉選單容器的引用 */
  readonly dropdownContainer = viewChild<ElementRef<HTMLElement>>('dropdownContainer');
  /** 所有選項列表項的引用 */
  readonly optionItems = viewChildren<ElementRef<HTMLElement>>('optionItem');

  private readonly elementRef = inject(ElementRef);

  constructor() {
    effect(() => {
      const selectedKey = this.selected();
      const option = this.displayOptions().find(opt => opt.value === selectedKey) || null;
      this.currentOption.set(option);
    });
  }

  /** 選擇選項 */
  selectOption(option: ApSelectOption) {
    if (this.disabled()) return;
    this.onSelect.emit(option.value);
    this.isOpen.set(false);
    this.currentOption.set(option);
  }

  /** 切換下拉選單開關 */
  toggle() {
    if (this.disabled()) return;
    this.isOpen.set(!this.isOpen());
    if (this.isOpen()) {
      // 延遲執行以確保選項已經渲染
      setTimeout(() => this.scrollToCurrentOption());
    }
  }

  /** 顯示欄位 */
  displayLabel = computed<string>(() => {
    if (this.currentOption()) {
      return this.currentOption()!.label;
    }
    return this.placeholder();
  });

  showContent = computed<boolean>(() => {
    if (this.currentOption() && this.currentOption()!.content) {
      return true;
    }
    return false;
  });

  currentContent = computed<string[]>(() => {
    if (this.currentOption() && this.currentOption()!.content) {
      return this.currentOption()!.content!;
    }
    return [];
  });

  @HostListener('document:click', ['$event'])
  /** 點擊文件時關閉下拉選單 */
  onDocumentClick(event: Event) {
    if (!this.elementRef.nativeElement.contains(event.target)) {
      this.isOpen.set(false);
    }
  }

  /** 滾動到當前選項 */
  private scrollToCurrentOption() {
    // 如果沒有當前選項，則不執行任何操作
    if (!this.currentOption()) return;

    // 找到當前選項對應的列表項目
    const currentOptionIndex = this.displayOptions().indexOf(this.currentOption()!);
    if (currentOptionIndex === -1) return;

    // 獲取對應的 DOM 元素
    const optionElements = this.optionItems();
    const targetElement = optionElements[currentOptionIndex]?.nativeElement;

    if (targetElement) {
      // 使用 scrollIntoView 滾動到可見區域
      targetElement.scrollIntoView({
        behavior: 'auto',  // 瞬間滾動
        block: 'nearest',    // 垂直方向：最近的邊緣
        inline: 'nearest'    // 水平方向：最近的邊緣
      });
    }
  }
}
